/**
 * Hand-written TypeScript types mirroring supabase/migrations/0001_init.sql.
 *
 * These are written by hand rather than generated by the Supabase CLI, because
 * Phase 1 has no database connection and nothing to generate from. When the
 * migration is eventually applied, `supabase gen types typescript` becomes the
 * source of truth and this file is replaced -- until then it is the contract,
 * and it must be edited in the same commit as any change to the SQL.
 *
 * Conventions:
 *   - Postgres `uuid`        -> string
 *   - Postgres `timestamptz` -> string (ISO 8601, as PostgREST returns it)
 *   - Postgres `numeric`     -> number  (see note on precision below)
 *   - Nullable columns       -> `| null`, never `?`. A column that exists and
 *                               is NULL is different from a key that is absent,
 *                               and collapsing the two hides real bugs.
 *   - Columns with a DB default are optional on Insert, required on Row.
 *   - Row and Insert shapes are declared with `type`, never `interface`.
 *
 * THAT LAST ONE IS LOAD-BEARING. postgrest-js requires every Row and Insert to
 * satisfy `Record<string, unknown>`. TypeScript gives object *type aliases* an
 * implicit index signature and deliberately does not give one to *interfaces*,
 * because an interface can be reopened by declaration merging and so its key
 * set is never final. An interface here therefore fails the library's
 * structural check -- and the failure is silent: the schema falls back to
 * `never`, and every query result in the app becomes `never` with the error
 * reported at the call site ("Property 'id' does not exist on type 'never'"),
 * nowhere near this file. Do not convert these back to interfaces.
 *
 * NOTE ON `numeric`: Postgres numeric is arbitrary-precision; JS number is a
 * double. Every numeric column here (kd_ratio, avg_damage, rates) is a small
 * magnitude with at most 3 decimal places, so the double representation is
 * exact enough. Do not add a high-precision numeric column without revisiting
 * this -- it would need to be typed as string.
 */

// ---------------------------------------------------------------------------
// Enums -- mirror of SECTION 1 of 0001_init.sql
// ---------------------------------------------------------------------------

/** BGMI squad roles. `flex` is a competence, not "unassigned" -- absence is null. */
export type PlayerRole =
  | 'igl'
  | 'assaulter'
  | 'sniper'
  | 'support'
  | 'flex';

/** Lifecycle of one matchmaking_queue row. */
export type QueueState =
  | 'waiting'
  | 'matching'
  | 'matched'
  | 'cancelled'
  | 'expired';

/** Lifecycle of one match. */
export type MatchStatus =
  | 'forming'
  | 'ready'
  | 'in_progress'
  | 'completed'
  | 'abandoned';

/** Communication requirement. Applied as a hard filter, not a weight. */
export type CommPreference =
  | 'voice_required'
  | 'voice_optional'
  | 'text_only'
  | 'silent';

/**
 * Which scorer produced `matches.synergy_score`.
 * Modelled as text + CHECK in SQL rather than an enum -- see the fallback path
 * in docs/architecture.md section 4.
 */
export type ScoringSource = 'ml' | 'rule_based';

/** Runtime-usable lists, for validation and for populating select inputs. */
export const PLAYER_ROLES: readonly PlayerRole[] = [
  'igl',
  'assaulter',
  'sniper',
  'support',
  'flex',
] as const;

export const QUEUE_STATES: readonly QueueState[] = [
  'waiting',
  'matching',
  'matched',
  'cancelled',
  'expired',
] as const;

export const MATCH_STATUSES: readonly MatchStatus[] = [
  'forming',
  'ready',
  'in_progress',
  'completed',
  'abandoned',
] as const;

export const COMM_PREFERENCES: readonly CommPreference[] = [
  'voice_required',
  'voice_optional',
  'text_only',
  'silent',
] as const;

// ---------------------------------------------------------------------------
// Shared aliases
//
// These carry no extra type safety on their own -- they are documentation at
// the point of use, so a reader of a function signature can tell a uuid from a
// display name without opening this file.
// ---------------------------------------------------------------------------

/** UUID v4, as produced by gen_random_uuid(). */
export type UUID = string;

/** ISO 8601 timestamp with timezone. */
export type Timestamptz = string;

/**
 * A 0-100 normalized score. CHECK-constrained in Postgres; TypeScript cannot
 * express the range, so the alias exists to make the intent visible and to give
 * validators in lib/ a single name to key on.
 */
export type Score0To100 = number;

// ---------------------------------------------------------------------------
// profiles
// ---------------------------------------------------------------------------

export type Profile = {
  id: UUID;
  /**
   * null     = synthetic seed profile (ML training data, no human behind it)
   * non-null = real authenticated user
   * UNIQUE in the database: at most one profile per auth account.
   */
  auth_user_id: UUID | null;
  display_name: string;
  /** In-game name. UNIQUE -- the key used to reconcile external match records. */
  bgmi_ign: string;
  region: string | null;
  avatar_url: string | null;
  bio: string | null;
  is_active: boolean;
  /** Synthetic row written by scripts/seed.ts (0005). */
  is_seed: boolean;
  /** May form squads and reset demo tournaments (0006). Service-role writes only. */
  is_organiser: boolean;
  created_at: Timestamptz;
  updated_at: Timestamptz;
}

export type ProfileInsert = {
  id?: UUID;
  auth_user_id?: UUID | null;
  display_name: string;
  bgmi_ign: string;
  region?: string | null;
  avatar_url?: string | null;
  bio?: string | null;
  is_active?: boolean;
  is_seed?: boolean;
  is_organiser?: boolean;
  created_at?: Timestamptz;
  updated_at?: Timestamptz;
}

export type ProfileUpdate = Partial<ProfileInsert>;

// ---------------------------------------------------------------------------
// player_stats -- 1:1 with profiles. Written by the ML service.
// ---------------------------------------------------------------------------

export type PlayerStats = {
  id: UUID;
  profile_id: UUID;

  // Raw performance figures.
  kd_ratio: number;
  avg_damage: number;
  /** Seconds. */
  avg_survival_time: number;
  /** Percent, 0-100. */
  headshot_rate: number;
  /** Percent, 0-100. */
  win_rate: number;

  // Normalized skill axes. Every one is CHECK-constrained 0-100 in Postgres.
  aim_score: Score0To100;
  game_sense: Score0To100;
  teamwork_score: Score0To100;
  clutch_score: Score0To100;
  consistency_score: Score0To100;
  /** Composite of the five axes. Stored, not computed -- the weighting is owned
   *  by the ML service and changes between model versions. */
  overall_rating: Score0To100;

  matches_played: number;
  matches_won: number;

  /** null = never scored. Distinct from "scored and landed on the defaults". */
  last_computed_at: Timestamptz | null;

  /** Synthetic row written by scripts/seed.ts (0005). */
  is_seed: boolean;
  created_at: Timestamptz;
  updated_at: Timestamptz;
}

export type PlayerStatsInsert = {
  id?: UUID;
  profile_id: UUID;
  kd_ratio?: number;
  avg_damage?: number;
  avg_survival_time?: number;
  headshot_rate?: number;
  win_rate?: number;
  aim_score?: Score0To100;
  game_sense?: Score0To100;
  teamwork_score?: Score0To100;
  clutch_score?: Score0To100;
  consistency_score?: Score0To100;
  overall_rating?: Score0To100;
  matches_played?: number;
  matches_won?: number;
  last_computed_at?: Timestamptz | null;
  is_seed?: boolean;
  created_at?: Timestamptz;
  updated_at?: Timestamptz;
}

export type PlayerStatsUpdate = Partial<Omit<PlayerStatsInsert, 'profile_id'>>;

// ---------------------------------------------------------------------------
