// ---------------------------------------------------------------------------
// player_availability -- 1:N per profile.
// ---------------------------------------------------------------------------

/** 0 = Sunday ... 6 = Saturday. Matches both JS getDay() and Postgres dow. */
export type DayOfWeek = 0 | 1 | 2 | 3 | 4 | 5 | 6;

export type PlayerAvailability = {
  id: UUID;
  profile_id: UUID;
  day_of_week: DayOfWeek;
  /** Minutes from local midnight, 0-1440. start < end is enforced in the DB. */
  start_minute: number;
  end_minute: number;
  /** -720 (UTC-12) to +840 (UTC+14). */
  timezone_offset_minutes: number;
  /** Synthetic row written by scripts/seed.ts (0005). */
  is_seed: boolean;
  created_at: Timestamptz;
  updated_at: Timestamptz;
}

export type PlayerAvailabilityInsert = {
  id?: UUID;
  profile_id: UUID;
  day_of_week: DayOfWeek;
  start_minute: number;
  end_minute: number;
  timezone_offset_minutes?: number;
  is_seed?: boolean;
  created_at?: Timestamptz;
  updated_at?: Timestamptz;
}

export type PlayerAvailabilityUpdate = Partial<
  Omit<PlayerAvailabilityInsert, 'profile_id'>
>;

// ---------------------------------------------------------------------------
// matchmaking_queue
// ---------------------------------------------------------------------------

export type MatchmakingQueueEntry = {
  id: UUID;
  /** UNIQUE -- a player is in the pool at most once. */
  profile_id: UUID;
  state: QueueState;
  /** null = no role preference for this queue entry. */
  desired_role: PlayerRole | null;
  /** Snapshot of the preference band taken at enqueue time, deliberately not a
   *  join: the matcher must see a stable band even if preferences are edited. */
  min_skill: Score0To100;
  max_skill: Score0To100;
  party_size: number;
  target_squad_size: number;
  region: string | null;
  enqueued_at: Timestamptz;
  /** null = no expiry set. */
  expires_at: Timestamptz | null;
  /**
   * Non-null if and only if `state === 'matched'`. Enforced by a CHECK in
   * Postgres; the discriminated union below makes the same guarantee usable by
   * the type checker.
   */
  matched_match_id: UUID | null;
  created_at: Timestamptz;
  updated_at: Timestamptz;
}

/**
 * Type-level mirror of the `matchmaking_queue_matched_requires_match` CHECK.
 * Narrowing on `state` gives you `matched_match_id` without a null assertion.
 */
export type MatchmakingQueueEntryChecked =
  | (Omit<MatchmakingQueueEntry, 'state' | 'matched_match_id'> & {
      state: 'matched';
      matched_match_id: UUID;
    })
  | (Omit<MatchmakingQueueEntry, 'state' | 'matched_match_id'> & {
      state: Exclude<QueueState, 'matched'>;
      matched_match_id: null;
    });

export type MatchmakingQueueInsert = {
  id?: UUID;
  profile_id: UUID;
  state?: QueueState;
  desired_role?: PlayerRole | null;
  min_skill?: Score0To100;
  max_skill?: Score0To100;
  party_size?: number;
  target_squad_size?: number;
  region?: string | null;
  enqueued_at?: Timestamptz;
  expires_at?: Timestamptz | null;
  matched_match_id?: UUID | null;
  created_at?: Timestamptz;
  updated_at?: Timestamptz;
}

export type MatchmakingQueueUpdate = Partial<
  Omit<MatchmakingQueueInsert, 'profile_id'>
>;

