// ---------------------------------------------------------------------------
// Aggregate schema type
//
// Shaped to match what `supabase gen types typescript` emits, so that swapping
// this file for a generated one in Phase 2 does not require touching call
// sites: createClient<Database>(...) keeps working unchanged.
// ---------------------------------------------------------------------------

/**
 * `Relationships: []` on every table is required, not decorative.
 *
 * postgrest-js checks the schema against its own `GenericTable`, which declares
 * `Relationships: GenericRelationship[]`. Omitting the key does not produce an
 * error at the type definition -- it makes the schema fail that structural
 * check, and every query result silently degrades to `never`. The symptom is
 * `Property 'id' does not exist on type 'never'` at the call site, a long way
 * from the cause.
 *
 * Empty arrays are honest here: the arrays describe embedded-resource joins
 * (`select('*, player_stats(*)')`), and Phase 2 issues none. Generated types
 * will populate them from the real foreign keys when this file is replaced.
 */
export interface Database {
  public: {
    Tables: {
      profiles: {
        Row: Profile;
        Insert: ProfileInsert;
        Update: ProfileUpdate;
        Relationships: [];
      };
      player_stats: {
        Row: PlayerStats;
        Insert: PlayerStatsInsert;
        Update: PlayerStatsUpdate;
        Relationships: [];
      };
      player_preferences: {
        Row: PlayerPreferences;
        Insert: PlayerPreferencesInsert;
        Update: PlayerPreferencesUpdate;
        Relationships: [];
      };
      player_availability: {
        Row: PlayerAvailability;
        Insert: PlayerAvailabilityInsert;
        Update: PlayerAvailabilityUpdate;
        Relationships: [];
      };
      matchmaking_queue: {
        Row: MatchmakingQueueEntry;
        Insert: MatchmakingQueueInsert;
        Update: MatchmakingQueueUpdate;
        Relationships: [];
      };
      matches: {
        Row: Match;
        Insert: MatchInsert;
        Update: MatchUpdate;
        Relationships: [];
      };
      match_participants: {
        Row: MatchParticipant;
        Insert: MatchParticipantInsert;
        Update: MatchParticipantUpdate;
        Relationships: [];
      };
      match_feedback: {
        Row: MatchFeedback;
        Insert: MatchFeedbackInsert;
        Update: MatchFeedbackUpdate;
        Relationships: [];
      };
      tournaments: {
        Row: Tournament;
        Insert: TournamentInsert;
        Update: TournamentUpdate;
        Relationships: [];
      };
      tournament_registrations: {
        Row: TournamentRegistration;
        Insert: TournamentRegistrationInsert;
        Update: Partial<TournamentRegistrationInsert>;
        Relationships: [];
      };
      model_versions: {
        Row: ModelVersion;
        Insert: ModelVersionInsert;
        Update: Partial<ModelVersionInsert>;
        Relationships: [];
      };
    };
    Views: {
      leaderboard_v: {
        Row: LeaderboardRow;
        Relationships: [];
      };
    };
    Functions: {
      public_stats: {
        Args: Record<string, never>;
        Returns: { players: number; tournaments: number; squads_formed: number }[];
      };
      analytics_overview: {
        Args: Record<string, never>;
        Returns: Json;
      };
    };
    Enums: {
      player_role: PlayerRole;
      queue_state: QueueState;
      match_status: MatchStatus;
      comm_preference: CommPreference;
      tournament_status: TournamentStatus;
    };
  };
}

/** Convenience accessors, so call sites read as `Tables<'profiles'>`. */
export type Tables<T extends keyof Database['public']['Tables']> =
  Database['public']['Tables'][T]['Row'];

export type TablesInsert<T extends keyof Database['public']['Tables']> =
  Database['public']['Tables'][T]['Insert'];

export type TablesUpdate<T extends keyof Database['public']['Tables']> =
  Database['public']['Tables'][T]['Update'];

// ---------------------------------------------------------------------------
// Composite shapes
//
// Not tables. These are the joined views the recommender and the UI actually
// operate on, named here so the shape of a scorer's input is a declared
// contract rather than an ad-hoc object literal.
// ---------------------------------------------------------------------------

/** A player with everything the scorer needs, in one object. */
export interface PlayerVector {
  profile: Profile;
  stats: PlayerStats | null;
  preferences: PlayerPreferences | null;
  availability: PlayerAvailability[];
}

/** One seat in a proposed squad. */
export interface RoleAssignment {
  profile_id: UUID;
  assigned_role: PlayerRole;
}

/**
 * The return shape shared by BOTH scorers. The ML client and the rule-based
 * fallback in lib/ implement this identically -- which is what allows the
 * caller in app/ to swap between them without a branch in its own logic.
 */
export interface SquadScore {
  synergy_score: Score0To100;
  assignments: RoleAssignment[];
  scoring_source: ScoringSource;
}
